void  per_exec_init( void )
{
    static Boolean do_one_time = TRUE ; 

	if( do_one_time )
	{	
		per_exec_pte = os_pte_create( PER_EXEC_UPDATE_PERIOD_MS ); 

		per_exec_tsk = os_tsk_create( (TskFunc)per_exec_tsk_func , TASK_PER_EXEC_PRI , TASK_PER_EXEC_STK , 0 , TASK_PER_EXEC_NAME );

		per_exec_reg = reg_table_create(REG_ATOMIC_USE_RES); 

		os_tsk_start( per_exec_tsk , NULL ); 

		do_one_time = FALSE ; 
	}
}

